import"./chunk-2NFLSA4Y.js";var i={doubleSlit:{theory:{concept:"[[Interference of light is the overlapping of light waves from one source, which produces bright and dark fringes: in some places the waves strengthen each other, in others they cancel.]] In Young's double-slit experiment light from one source passes through two narrow slits. Where crests from both slits arrive together, the screen is bright; where a crest meets a trough, it is dark. Interference shows that light behaves as a wave."},section:{setup:{title:"How is the experiment arranged?",text:"A single monochromatic source illuminates two nearby slits. [[Both slits act as coherent sources, meaning their relative phase stays steady.]] A screen records brightness at many positions. The moving detector in the simulation scans that screen."},interference:{title:"Bright and dark fringes",text:"At the centre the two paths have equal length, so the waves reinforce. Away from the centre their path lengths differ. A whole-number wavelength difference makes a bright fringe; a half-number wavelength difference makes a dark fringe."},spacing:{title:"What changes the spacing?",text:"[[Near the centre, fringe spacing is approximately \u0394y = \u03BBL/d.]] Longer wavelengths or a farther screen spread the fringes apart. Moving the slits farther apart brings the fringes closer together."},envelope:{title:"Why do outer fringes fade?",text:"Each slit has a finite width. Diffraction from one slit forms a broad brightness envelope, which reduces the outer fringes. The exact pattern combines this envelope with the interference of the two slits."},quantum:{title:"One particle at a time",text:"The stripes appear even when the light is so weak that only one photon passes at a time: each photon lands as a single dot, and the pattern builds up dot by dot. Electrons, atoms and even molecules of about 2 000 atoms (2019) do the same. This experiment is one of the clearest signs that light and matter behave both as waves and as particles \u2014 the starting point of quantum physics."},try:{title:"Try it",text:"Increase the wavelength while keeping the apparatus fixed. Count how many bright fringes fit on the same screen. Then change the slit separation. Can you predict which change makes the fringes wider?"}},formula:{spacing:"Approximate central fringe spacing for small angles",bright:"Bright fringes: path difference equals an integer number of wavelengths",dark:"Dark fringes: path difference equals a half-integer number of wavelengths",intensity:"Far-field intensity with a finite-slit diffraction envelope and visibility V"},variable:{wavelength:"Light wavelength",separation:"Distance between slit centres",distance:"Distance from slits to screen",spacing:"Spacing between central bright fringes",intensity:"Brightness relative to the central maximum"},assumption:{farField:"The screen is far from two equal, uniformly illuminated narrow slits. The Fraunhofer approximation applies; the simple spacing formula is most accurate near the centre.",coherence:"The default source is monochromatic and perfectly coherent. The visibility control only scales fringe contrast; it does not model a particular partially coherent source.",scale:"The slit separation, screen distance and fringe spacing differ by many orders of magnitude. Their drawing sizes are deliberately not to scale; use the measurements for physical distances.",animation:"Wavefronts and the detector scan are slowed diagrams. They do not show the actual speed or optical-frequency oscillation of light."},param:{wavelength:"Light wavelength",slitSeparation:"Slit separation",screenDistance:"Screen distance",slitWidth:"Width of each slit",visibility:"Fringe visibility",timeStep:"Simulation timestep"},hint:{wavelength:"Visible light is roughly 380\u2013750 nm; this control uses a safe middle range.",slitSeparation:"Distance between the centres of the two openings.",screenDistance:"Physical distance from the slit barrier to the screen.",slitWidth:"A wider slit narrows the outer diffraction envelope.",visibility:"1 gives full contrast; 0 removes the two-slit fringes while retaining the single-slit envelope."},measure:{fringeSpacing:"Central fringe spacing (approx.)",detectorY:"Detector position",intensity:"Relative brightness",firstDark:"First dark fringe from centre (approx.)",visibility:"Fringe visibility"},visual:{wavefronts:"Schematic wavefronts"},view:{source:"Light source",slits:"Two slits",screen:"Screen",notToScale:"Diagram not to scale"},graph:{profile:"Brightness across the screen"},challenge:{wide:{title:"Spread the fringes",description:"Make the central bright fringes at least 3 mm apart.",hint:"Try a longer wavelength, a farther screen or closer slits."},narrow:{title:"Pack the fringes",description:"Make the central bright fringes no more than 1 mm apart.",hint:"Try a shorter wavelength, a nearer screen or wider slit separation."},red:{title:"Long wavelength",description:"Use light of at least 650 nm and obtain fringe spacing of at least 2.5 mm.",hint:"Move the screen farther away if changing the wavelength is not enough."},washout:{title:"No two-slit contrast",description:"Remove the two-slit fringes by setting their visibility to zero.",hint:"The broad single-slit envelope remains."}}}},a={sim:i};export{a as default,i as sim};
